CREATE TABLE public.production_enrollments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_id uuid NOT NULL UNIQUE REFERENCES public.students(id) ON DELETE CASCADE, instructor_id uuid NOT NULL REFERENCES public.instructors(id), level text NOT NULL DEFAULT 'novice' CHECK (level IN ('novice','amateur','intermediate','advanced','advanced_plus')), class_day text, class_time text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.production_enrollments TO authenticated; GRANT ALL ON public.production_enrollments TO service_role;
ALTER TABLE public.production_enrollments ENABLE ROW LEVEL SECURITY;
CREATE POLICY production_enrollment_read ON public.production_enrollments FOR SELECT TO authenticated USING (student_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR (instructor_id=auth.uid() AND public.has_role(auth.uid(),'instructor')));
CREATE POLICY production_enrollment_staff ON public.production_enrollments FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin') OR (instructor_id=auth.uid() AND public.has_role(auth.uid(),'instructor') AND public.can_instructor_access_student(auth.uid(),student_id))) WITH CHECK (public.has_role(auth.uid(),'admin') OR (instructor_id=auth.uid() AND public.has_role(auth.uid(),'instructor') AND public.can_instructor_access_student(auth.uid(),student_id)));
CREATE TRIGGER production_enrollment_updated BEFORE UPDATE ON public.production_enrollments FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TABLE public.production_modules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, description text NOT NULL DEFAULT '', lesson_outline text NOT NULL DEFAULT '', homework_prompt text NOT NULL DEFAULT '', level text NOT NULL CHECK (level IN ('novice','amateur','intermediate','advanced','advanced_plus')), order_index integer NOT NULL DEFAULT 1, author_id uuid REFERENCES public.profiles(id), is_draft boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.production_modules TO authenticated; GRANT ALL ON public.production_modules TO service_role;
ALTER TABLE public.production_modules ENABLE ROW LEVEL SECURITY;
CREATE POLICY production_module_read ON public.production_modules FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'instructor') OR (NOT is_draft AND public.has_role(auth.uid(),'student')));
CREATE POLICY production_module_staff ON public.production_modules FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin') OR (public.has_role(auth.uid(),'instructor') AND (author_id=auth.uid() OR author_id IS NULL))) WITH CHECK (public.has_role(auth.uid(),'admin') OR (public.has_role(auth.uid(),'instructor') AND author_id=auth.uid()));
CREATE TRIGGER production_module_updated BEFORE UPDATE ON public.production_modules FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TABLE public.production_module_completions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), enrollment_id uuid NOT NULL REFERENCES public.production_enrollments(id) ON DELETE CASCADE, module_id uuid NOT NULL REFERENCES public.production_modules(id) ON DELETE CASCADE, completed_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(enrollment_id,module_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.production_module_completions TO authenticated; GRANT ALL ON public.production_module_completions TO service_role;
ALTER TABLE public.production_module_completions ENABLE ROW LEVEL SECURITY;
CREATE POLICY production_completion_read ON public.production_module_completions FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.production_enrollments e WHERE e.id=enrollment_id AND (e.student_id=auth.uid() OR e.instructor_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE POLICY production_completion_staff ON public.production_module_completions FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin') OR (public.has_role(auth.uid(),'instructor') AND EXISTS (SELECT 1 FROM public.production_enrollments e WHERE e.id=enrollment_id AND e.instructor_id=auth.uid()))) WITH CHECK (public.has_role(auth.uid(),'admin') OR (public.has_role(auth.uid(),'instructor') AND EXISTS (SELECT 1 FROM public.production_enrollments e WHERE e.id=enrollment_id AND e.instructor_id=auth.uid())));
CREATE TRIGGER production_completion_updated BEFORE UPDATE ON public.production_module_completions FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TABLE public.production_attendance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), enrollment_id uuid NOT NULL REFERENCES public.production_enrollments(id) ON DELETE CASCADE, class_date date NOT NULL, status text NOT NULL CHECK(status IN ('present','absent')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(enrollment_id,class_date));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.production_attendance TO authenticated; GRANT ALL ON public.production_attendance TO service_role;
ALTER TABLE public.production_attendance ENABLE ROW LEVEL SECURITY;
CREATE POLICY production_attendance_read ON public.production_attendance FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.production_enrollments e WHERE e.id=enrollment_id AND (e.student_id=auth.uid() OR e.instructor_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE POLICY production_attendance_staff ON public.production_attendance FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin') OR (public.has_role(auth.uid(),'instructor') AND EXISTS (SELECT 1 FROM public.production_enrollments e WHERE e.id=enrollment_id AND e.instructor_id=auth.uid()))) WITH CHECK (public.has_role(auth.uid(),'admin') OR (public.has_role(auth.uid(),'instructor') AND EXISTS (SELECT 1 FROM public.production_enrollments e WHERE e.id=enrollment_id AND e.instructor_id=auth.uid())));
CREATE TRIGGER production_attendance_updated BEFORE UPDATE ON public.production_attendance FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
INSERT INTO public.production_modules(title,description,lesson_outline,homework_prompt,level,order_index) VALUES
('Your DAW & first session','Draft: session setup and a first musical sketch.','Navigate the DAW; set tempo; organize tracks; save a session.','Create and save an eight-bar sketch.','novice',1),
('Rhythm & arrangement basics','Draft: build a simple loop and develop an arrangement.','Program drums; arrange contrasting sections; export a reference bounce.','Turn your sketch into a short arranged track.','novice',2),
('Composition & sound selection','Draft: develop a musical idea with intentional sounds.','Explore melody, harmony and complementary sound choices.','Create two contrasting variations of one musical idea.','amateur',1),
('Sampling & song structure','Draft: shape samples and a complete arrangement.','Edit samples; build transitions; compare reference arrangements.','Arrange a complete demo with an intro and ending.','amateur',2),
('Synthesis & sound design','Draft: create original sounds for a project.','Explore oscillators, envelopes, modulation and automation.','Create a small sound palette and use it in a track.','intermediate',1),
('Mixing foundations','Draft: balance a mix with references.','Gain staging; EQ; compression; spatial effects; reference listening.','Submit a balanced mix and a short reflection.','intermediate',2),
('Project development','Draft: develop a release-focused track.','Set project milestones; refine arrangement; revise from mentor feedback.','Complete a revised production with a revision log.','advanced',1),
('Finishing & delivery','Draft: prepare a finished production for delivery.','Evaluate translation; check exports; organize stems and session files.','Prepare a final bounce and organized delivery folder.','advanced',2),
('Mentorship project','Draft: an open-ended creative project; no fixed week count.','Agree on goals, project scope and the next mentor-led milestone.','Share a work-in-progress and questions for the next session.','advanced_plus',1),
('Portfolio & creative direction','Draft: ongoing portfolio, album or specialist development.','Review portfolio direction; explore genre, mixing or sound-design goals.','Set the next project milestone with your mentor.','advanced_plus',2);